public class CacheDemo {
    static final int N = 4096;

    static long sumRowMajor(int[][] m) {
        long s = 0;
        for (int i = 0; i < N; i++)
            for (int j = 0; j < N; j++) s += m[i][j];
        return s;
    }

    static long sumColMajor(int[][] m) {
        long s = 0;
        for (int j = 0; j < N; j++)
            for (int i = 0; i < N; i++) s += m[i][j];
        return s;
    }

    public static void main(String[] args) {
        int[][] m = new int[N][N];
        for (int i = 0; i < N; i++) java.util.Arrays.fill(m[i], 1);
        for (int r = 0; r < 3; r++) {
            long t0 = System.nanoTime();
            long a = sumRowMajor(m);
            long t1 = System.nanoTime();
            long b = sumColMajor(m);
            long t2 = System.nanoTime();
            System.out.printf("row-major %4d ms, column-major %4d ms (sum %d, %d)%n",
                    (t1 - t0) / 1_000_000, (t2 - t1) / 1_000_000, a, b);
        }
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Random;

public class Layout {
    public static void main(String[] args) {
        int n = 4_000_000;
        int[] prim = new int[n];
        List<Integer> boxed = new ArrayList<>(n);
        for (int i = 0; i < n; i++) { prim[i] = i % 1000 + 1000; boxed.add(prim[i]); }
        List<Integer> shuffled = new ArrayList<>(boxed);
        Collections.shuffle(shuffled, new Random(1));
        for (int r = 0; r < 4; r++) {
            long t0 = System.nanoTime();
            long a = 0;
            for (int v : prim) a += v;
            long t1 = System.nanoTime();
            long b = 0;
            for (int v : boxed) b += v;
            long t2 = System.nanoTime();
            long c = 0;
            for (int v : shuffled) c += v;
            long t3 = System.nanoTime();
            System.out.printf("int[] %3d ms | boxed in order %3d ms | "
                    + "boxed shuffled %3d ms (%d %d %d)%n",
                    (t1 - t0) / 1_000_000, (t2 - t1) / 1_000_000,
                    (t3 - t2) / 1_000_000, a, b, c);
        }
    }
}

#include <stdio.h>
