static long raw_write(int fd, const char *buf, unsigned long len) {
    long ret;
    __asm__ volatile("syscall"
                     : "=a"(ret)
                     : "a"(1L), "D"((long)fd), "S"(buf), "d"(len)
                     : "rcx", "r11", "memory");
    return ret;
}

int main(void) {
    const char msg[] = "written with a raw SYSCALL instruction\n";
    long n = raw_write(1, msg, sizeof msg - 1);
    printf("returned %ld\n", n);
    long bad = raw_write(99, msg, 3);
    printf("write to fd 99 returned %ld (negative errno, -EBADF = -9)\n", bad);
    return 0;
}

