#include <stdio.h>
#include <time.h>
#include <unistd.h>
#include <sys/syscall.h>

static double now_ns(void) {
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec * 1e9 + t.tv_nsec;
}

static volatile long sink;

__attribute__((noinline)) long plain_call(long x) { return x + 1; }

int main(void) {
    const long N = 2000000;
    double t0, t1;
    struct timespec ts;

    t0 = now_ns();
    for (long i = 0; i < N; i++) sink = plain_call(i);
    t1 = now_ns();
    printf("function call        : %7.1f ns/call\n", (t1 - t0) / N);

    t0 = now_ns();
    for (long i = 0; i < N; i++) sink = syscall(SYS_getppid);
    t1 = now_ns();
    printf("getppid() syscall    : %7.1f ns/call\n", (t1 - t0) / N);

    t0 = now_ns();
    for (long i = 0; i < N; i++) clock_gettime(CLOCK_MONOTONIC, &ts);
    t1 = now_ns();
    printf("clock_gettime (vDSO) : %7.1f ns/call\n", (t1 - t0) / N);

    t0 = now_ns();
    for (long i = 0; i < N; i++)
        sink = syscall(SYS_clock_gettime, CLOCK_MONOTONIC, &ts);
    t1 = now_ns();
    printf("clock_gettime (trap) : %7.1f ns/call\n", (t1 - t0) / N);
    return 0;
}

