        boolean buffered = args[0].equals("buffered");
        int n = 200_000;
        long t0 = System.nanoTime();
        try (OutputStream raw = new FileOutputStream("/tmp/osw_o1/bytes.dat");
             OutputStream out = buffered ? new BufferedOutputStream(raw, 8192) : raw) {
